-- Prepared only: authenticated Intake editing; retire personal training.
-- FIRST run the separately reviewed, exact-record training cleanup if necessary.
-- No business data is modified here. Nonempty training registry fails closed.
begin;
lock table public.intake_training_workflows, public.intake_training_grants in access exclusive mode;
do $guard$
declare actual jsonb;
begin
-- Read-only authorization fingerprint, excluding business rows and volatile OIDs.
select jsonb_build_object(
 'capabilities',(select jsonb_agg(jsonb_build_array(role,capability) order by role,capability) from public.app_role_capabilities where capability in ('viewIntake','accessIntake','createProductionJob','scheduleProduction','manageUsers')),
